        assert.equal(re.exec('key = gh-12')[1], 'gh-12');
        assert.equal(re.exec('key = acme/w#12')[1], 'acme/w#12');
        assert.equal(re.exec('key = #12')[1], '#12');
        assert.equal(re.exec('key = 12')[1], '12');
        assert.equal(re.exec('key = PROJ-12'), null);
    });

});
