    var gh = jql.match(/key\s*(?:=|in\s*\()\s*(gh-\d+|[\w.-]+\/[\w.-]+#\d+|#\d+|\d+)/i);
    if (gh && gh[1]) return gh[1];
    var m = jql.match(/key\s*(?:=|in\s*\()\s*([A-Z][A-Z0-9_]*-\d+)/i);
