        var trackers = loadTrackers({ jira_post_comment: jiraPost });
        trackers.createTracker({ tracker: { provider: 'jira' } }).postComment('gh-5', 'x');
        assert.equal(jiraPost.calls[0].key, 'gh-5');
    });
});

