// 'owner/repo#N' the composite form, '#N' and bare 'N' appear in dispatch
// payloads. A tracker-agnostic gate must not abort GitHub-backed legs with
// "Invalid or missing Jira ticket key".
var GITHUB_KEY_SHAPES = [
    /^gh-\d+$/i,
    /^[\w.-]+\/[\w.-]+#\d+$/,
    /^#\d+$/,
    /^\d+$/
